<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;class User extends Authenticatable{use HasFactory,Notifiable;protected $fillable=['name','email','password','role'];protected $hidden=['password','remember_token'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];}public function isAdmin():bool{return in_array($this->role,['superadmin','admin','editor','teacher'],true);}public function hasRole(string ...$roles):bool{return in_array($this->role,$roles,true);}public function isSuperAdmin():bool{return $this->role==='superadmin';}}